const response=$input.first().json; const claimed=$('Jobs по одному').item.json;
function boundedUsage(value){const out={};for(const key of ['input_tokens','cached_input_tokens','output_tokens','reasoning_output_tokens']){const n=Number(value?.[key]);out[key]=Number.isSafeInteger(n)&&n>=0?n:0;}return out;}
function allowedArtifact(value){const out={};const validation=value?.failure?.validation;if(validation&&typeof validation==='object'){if(typeof validation.artifact==='string')out.validation_artifact=validation.artifact.slice(0,255);if(/^[0-9a-f]{64}$/iu.test(String(validation.sha256??'')))out.validation_sha256=String(validation.sha256).toUpperCase();if(typeof validation.envelope_available==='boolean')out.validation_envelope_available=validation.envelope_available;}return out;}
function monitorFailure(code,message){return [{json:{job_id:claimed.id,analysis_run_id:claimed.analysis_run_id,poll_owner_execution_id:claimed.poll_owner_execution_id,
outcome:'monitor_failure',error_code:String(code).slice(0,80),error_message:String(message).slice(0,500),usage:boundedUsage(null),artifacts:{}}}];}
if(Number(response.statusCode??200)!==200)return monitorFailure('MONITOR_STATUS_HTTP_FAILED','Runner status request failed');
const body=response.body??response;
for(const key of ['job_id','analysis_run_id','pipeline_version','field_catalog_version','field_catalog_sha256','input_manifest_sha256']){const expectedKey=key==='job_id'?'id':key;if(String(body[key]??'')!==String(claimed[expectedKey]??''))return monitorFailure('MONITOR_STATUS_IDENTITY_INVALID','Runner status identity mismatch');}
const status=String(body.status??'');
if(!['ready','running','validating','completed','failed'].includes(status))return monitorFailure('MONITOR_STATUS_INVALID','Runner returned unsupported status');
const failure=body.failure??{};const runnerAttempt=Number(body.attempt);
if(status==='failed'&&(!Number.isInteger(runnerAttempt)||runnerAttempt<1||runnerAttempt>2))return monitorFailure('MONITOR_STATUS_ATTEMPT_INVALID','Runner failure attempt is invalid');
return [{json:{job_id:claimed.id,analysis_run_id:claimed.analysis_run_id,pipeline_version:claimed.pipeline_version,
field_catalog_version:claimed.field_catalog_version,field_catalog_sha256:claimed.field_catalog_sha256,input_manifest_sha256:claimed.input_manifest_sha256,
poll_owner_execution_id:claimed.poll_owner_execution_id,status,outcome:status==='failed'?'runner_failed':status==='completed'?'completed':'nonterminal',
heartbeat_at:null,usage:boundedUsage(body.usage),artifacts:allowedArtifact(body),
error_code:String(failure.code??'RUNNER_FAILED').slice(0,80),error_message:String(failure.message??'Runner job failed').slice(0,500),
runner_attempt:Number.isInteger(runnerAttempt)?runnerAttempt:0,runner_retryable:failure.retryable===true}}];

const claimed=$('Нормализовать runner status').item.json;const response=$input.first().json;
function resultFailure(outcome,code,message){return [{json:{...claimed,outcome,error_code:String(code).slice(0,80),error_message:String(message).slice(0,500)}}];}
if(Number(response.statusCode??200)!==200)return resultFailure('monitor_failure','MONITOR_RESULT_HTTP_FAILED','Runner result request failed');
const body=response.body??response;const envelope=body?.validation;const result=body?.result;
if(!envelope||typeof envelope!=='object'||Array.isArray(envelope)||envelope.schema_version!=='tender_agent_validation_v1'||envelope.valid!==true)return resultFailure('contract_invalid','RESULT_CONTRACT_INVALID','Validation envelope is invalid');
if(String(body?.job_id??'')!==claimed.job_id||String(envelope.job_id??'')!==claimed.job_id)return resultFailure('contract_invalid','RESULT_IDENTITY_INVALID','Result job identity mismatch');
if(!result||typeof result!=='object'||Array.isArray(result)||result.schema_version!=='tender_agent_result_v1'||result.field_catalog_version!==claimed.field_catalog_version||result.field_catalog_sha256!==claimed.field_catalog_sha256||result.input_manifest_sha256!==claimed.input_manifest_sha256)return resultFailure('contract_invalid','RESULT_IDENTITY_INVALID','Result source identity mismatch');
if(!/^[0-9a-f]{64}$/iu.test(String(envelope.raw_result_sha256??''))||!/^[0-9a-f]{64}$/iu.test(String(envelope.validated_result_sha256??'')))return resultFailure('contract_invalid','RESULT_HASH_INVALID','Result artifact hash is invalid');
if(!Array.isArray(envelope.fields)||envelope.fields.length!==27||!Array.isArray(result.fields)||result.fields.length!==27||!Array.isArray(envelope.job_issues))return resultFailure('contract_invalid','RESULT_CONTRACT_INVALID','Result must contain exact typed arrays');
const fields=[];for(let index=0;index<27;index++){const field=result.fields[index];const validation=envelope.fields[index];if(!field||typeof field!=='object'||Array.isArray(field)||!validation||typeof validation!=='object'||Array.isArray(validation))return resultFailure('contract_invalid','RESULT_CONTRACT_INVALID','Result field entry is invalid');if(!Number.isInteger(field.field_index)||typeof field.field_key!=='string'||typeof field.status!=='string'||(field.value_text!==null&&typeof field.value_text!=='string')||!Number.isInteger(validation.field_index)||typeof validation.field_key!=='string'||typeof validation.status!=='string'||(validation.value_text!==null&&typeof validation.value_text!=='string')||!Array.isArray(validation.issues))return resultFailure('contract_invalid','RESULT_CONTRACT_INVALID','Result field property type is invalid');if(validation.field_index!==field.field_index||validation.field_key!==field.field_key||validation.status!==field.status||validation.value_text!==field.value_text)return resultFailure('contract_invalid','RESULT_CONTRACT_INVALID','Validation field identity mismatch');fields.push({...field,issues:validation.issues,result_json:field});}
const jobIssueCodes=[];for(const issue of envelope.job_issues.slice(0,100)){if(!issue||typeof issue!=='object'||Array.isArray(issue))return resultFailure('contract_invalid','RESULT_CONTRACT_INVALID','Validation job issue is invalid');jobIssueCodes.push(String(issue.code??'SCHEMA_INVALID').slice(0,80));}
return [{json:{...claimed,outcome:'completed_valid',raw_result_sha256:envelope.raw_result_sha256,validated_result_sha256:envelope.validated_result_sha256,fields,
validation_summary:{valid:true,raw_result_sha256:envelope.raw_result_sha256,validated_result_sha256:envelope.validated_result_sha256,job_issue_codes:jobIssueCodes},
artifacts:{raw_result_sha256:envelope.raw_result_sha256,validated_result_sha256:envelope.validated_result_sha256}}}];

