BEGIN;
SELECT
 $4::uuid AS analysis_run_id,
 $1::uuid AS agentic_job_id,
 set_config('tender.job_id',$1::text,true) AS job_setting,
 set_config('tender.poll_owner',$2::text,true) AS poll_owner_setting,
 set_config('tender.payload',$3::text,true) AS payload_setting,
 set_config('tender.analysis_run_id',$4::text,true) AS analysis_run_setting,
 set_config('tender.catalog_version',$5::text,true) AS catalog_setting,
 set_config('tender.validation_summary',$6::text,true) AS validation_setting,
 set_config('tender.artifacts',$7::text,true) AS artifacts_setting;
DO $agentic$
DECLARE
  payload jsonb := current_setting('tender.payload')::jsonb;
  actual_count integer;
  actual_keys text[];
  expected_keys constant text[] := ARRAY['procurement_subject','nm_price_with_vat','platform','procedure_type','application_deadline','application_review_date','results_date','customer','customer_contacts','participation_cost','participation_guarantee','evaluation_criteria','delivery_term','payment_terms','special_account_or_treasury','bank_support','government_contract','rebidding','national_regime','advance_contract_guarantee','warranty_obligations_guarantee','licenses_certificates','required_official_certificates','similar_supply_experience','analog_allowed','analog_definition','application_documents']::text[];
BEGIN
  PERFORM 1 FROM public.tender_agentic_jobs
   WHERE id=current_setting('tender.job_id')::uuid AND poll_owner_execution_id=current_setting('tender.poll_owner') AND status IN ('ready','running','validating')
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AGENTIC_POLL_OWNERSHIP_LOST'; END IF;
  SELECT count(*),array_agg(field_key ORDER BY field_index)
    INTO actual_count,actual_keys
    FROM jsonb_to_recordset(payload) AS f(field_index int,field_key text,status text,value_text text,issues jsonb,result_json jsonb);
  IF actual_count <> 27 OR actual_keys <> expected_keys THEN
    RAISE EXCEPTION 'AGENTIC_RESULT_FIELD_SET_MISMATCH';
  END IF;
  INSERT INTO public.tender_agentic_field_results(
    job_id,analysis_run_id,field_catalog_version,field_index,field_key,status,value_text,validation_issues,result_json
  )
  SELECT current_setting('tender.job_id')::uuid,current_setting('tender.analysis_run_id')::uuid,current_setting('tender.catalog_version'),f.field_index,f.field_key,f.status,f.value_text,coalesce(f.issues,'[]'::jsonb),f.result_json
  FROM jsonb_array_elements(payload) item
  CROSS JOIN LATERAL jsonb_to_record(item) AS f(field_index int,field_key text,status text,value_text text,issues jsonb,result_json jsonb)
  ON CONFLICT (job_id, field_key) DO UPDATE SET
    field_index=EXCLUDED.field_index,status=EXCLUDED.status,value_text=EXCLUDED.value_text,
    validation_issues=EXCLUDED.validation_issues,result_json=EXCLUDED.result_json,updated_at=now();
  IF (SELECT count(*) FROM public.tender_agentic_field_results WHERE job_id=current_setting('tender.job_id')::uuid) <> 27
     OR (SELECT array_agg(field_key ORDER BY field_index) FROM public.tender_agentic_field_results WHERE job_id=current_setting('tender.job_id')::uuid) <> expected_keys THEN
    RAISE EXCEPTION 'AGENTIC_DB_FIELD_SET_MISMATCH';
  END IF;
  UPDATE public.tender_agentic_jobs SET status='completed',completed_at=coalesce(completed_at,now()),
    validation_summary=current_setting('tender.validation_summary')::jsonb,artifacts=current_setting('tender.artifacts')::jsonb,
    poll_owner_execution_id=NULL,poll_claimed_at=NULL,error_code=NULL,error_message=NULL,updated_at=now()
  WHERE id=current_setting('tender.job_id')::uuid AND poll_owner_execution_id=current_setting('tender.poll_owner') AND status IN ('ready','running','validating');
  IF NOT FOUND THEN RAISE EXCEPTION 'AGENTIC_COMPLETE_OWNERSHIP_LOST'; END IF;
END
$agentic$;
COMMIT;

